CREATE TABLE "parties" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL, "phone" TEXT NULL, "city" TEXT NULL, "kind" INTEGER NOT NULL, "notes" TEXT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)))
CREATE TABLE "orders" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "party_id" INTEGER NOT NULL REFERENCES parties (id) ON DELETE RESTRICT, "kind" INTEGER NOT NULL, "status" INTEGER NOT NULL DEFAULT 0, "date" INTEGER NOT NULL, "paid_piasters" INTEGER NOT NULL DEFAULT 0, "notes" TEXT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)))
CREATE TABLE "order_items" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "order_id" INTEGER NOT NULL REFERENCES orders (id) ON DELETE CASCADE, "name" TEXT NOT NULL, "quantity" REAL NOT NULL, "unit" TEXT NOT NULL DEFAULT 'قطعة', "unit_price_piasters" INTEGER NOT NULL)
CREATE TABLE "voice_notes" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "party_id" INTEGER NOT NULL REFERENCES parties (id) ON DELETE CASCADE, "order_id" INTEGER NULL REFERENCES orders (id) ON DELETE SET NULL, "file_name" TEXT NOT NULL, "duration_ms" INTEGER NOT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)))
